INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 14, 'theory', 'Quiz: Virtualization Security');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 14, 0, 'Where were guest escapes most often found?', '["In the scheduler", "In the guest''s file system", "In device emulation code", "In DNS"]', 2, 'An example is a bug in the emulation of a forgotten floppy disk controller in 2015.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 14, 1, 'How does the Prime+Probe attack work?', '["The attacker reads the victim''s memory directly", "The attacker replaces the firmware", "The attacker reboots the host", "The attacker fills the cache, the victim evicts some entries, and access times show which sets it used"]', 3, 'That is why cores and caches are not shared between untrusted tenants, and secret-handling code is written without data dependence.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 14, 2, 'Why is Foreshadow (L1TF) especially dangerous for virtualization?', '["A guest could shut down the host", "A guest could read data from the host''s first-level cache", "It broke the IOMMU", "It changed the BIOS"]', 1, 'The answer is microcode, flushing L1D on guest entry and disabling SMT between untrusted tenants.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 14, 3, 'What does confidential computing (SEV-SNP, TDX) provide?', '["Encryption of the network only", "Protection of the host''s disk", "Protection of the hypervisor''s source code", "VM memory is encrypted with a key the hypervisor can''t access and is protected from tampering"]', 3, 'The hypervisor still schedules the machine but can no longer read its memory.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 14, 4, 'What is remote attestation for?', '["The customer checks the processor-signed measurement of the image and only then releases secrets to the machine", "It speeds up migration", "It compresses the image", "It turns on KSM"]', 0, 'This is how the customer makes sure the machine is really running in protected mode.');
